/**
 * Translations keyed by Obsidian's language code.
 *
 * Covers every language Obsidian ships in the app — the entries marked
 * complete in obsidianmd/obsidian-translations. The codes that repo
 * still lists as work in progress (af, az, bg, dv, eo, eu, gl, hi, hr,
 * kn, ky, la, lt, ml, nan-TW, nn, oc, or, si, sl, sw, ta, te, tl, tt,
 * ur) aren't selectable in Obsidian yet, so they're left out; add them
 * here once they ship. Partial entries are fine — anything missing
 * falls back to English per key (see `t()`).
 *
 * `npm run check:lang` verifies that every locale's keys and {placeholders}
 * line up with the English source.
 */
